<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasDocumento, cambiarEstadoDocumentoCompraContable, guardarDocumentoCompraContable, listarDocumentosCompraContable } from '../services/documentosCompraContable'
import type { CuentaContableOption, DocumentoCompraContable, DocumentoCompraContablePayload } from '../interfaces/documentosCompraContable.interface'
const rows=ref<DocumentoCompraContable[]>([]),cuentas=ref<CuentaContableOption[]>([]),criterio=ref(''),cuentaQuery=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),searching=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<DocumentoCompraContablePayload>({codigo:'',nombre:'',tipoope:'0',afectacion:'S',cuenta_contable_prov_mn:null,cuenta_contable_prov_me:null,detraccion:false})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const operacion=(v:string)=>v==='0'?'Pago':v==='1'?'Ingreso':'Salida'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarDocumentosCompraContable(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:DocumentoCompraContable){editing.value=item?.id??null;Object.assign(form,{codigo:item?.codigo??'',nombre:item?.nombre??'',tipoope:item?.tipoope??'0',afectacion:item?.afectacion??'S',cuenta_contable_prov_mn:item?.cuenta_contable_prov_mn??null,cuenta_contable_prov_me:item?.cuenta_contable_prov_me??null,detraccion:item?.detraccion??false});cuentas.value=[];cuentaQuery.value='';error.value='';modal.value=true}
async function searchAccounts(){if(cuentaQuery.value.trim().length<3)return void(error.value='Ingrese al menos 3 caracteres para buscar una cuenta.');searching.value=true;try{cuentas.value=await buscarCuentasDocumento(cuentaQuery.value.trim())}catch(v){error.value=message(v)}finally{searching.value=false}}
async function save(){const codigo=form.codigo.trim(),nombre=form.nombre.trim();if(!codigo||codigo.length>10)return void(error.value='El código es obligatorio y admite hasta 10 caracteres.');if(nombre.length<2||nombre.length>50)return void(error.value='El nombre debe tener entre 2 y 50 caracteres.');saving.value=true;try{await guardarDocumentoCompraContable(editing.value,{...form,codigo:codigo.toUpperCase(),nombre:nombre.toUpperCase()});modal.value=false;success.value=`Documento ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:DocumentoCompraContable){if(!confirm(`¿Desea ${item.activo?'desactivar':'activar'} ${item.codigo}?`))return;try{await cambiarEstadoDocumentoCompraContable(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Documentos para compras</nav><header class="hero"><div class="mark">DC</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Documentos para compras</h1><p>Configura documentos, operación, afectación y cuentas contables de proveedores.</p></div><strong>{{total}} documentos</strong><button @click="open()">+ Nuevo documento</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por código o nombre"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando documentos…</div><div v-else-if="!rows.length" class="empty">No se encontraron documentos para compras.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Nombre</th><th>Operación</th><th>Afectación</th><th>Cuenta MN</th><th>Cuenta ME</th><th>Detracción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td>{{operacion(item.tipoope)}}</td><td>{{item.afectacion==='S'?'Afecto':'Inafecto'}}</td><td>{{item.cuenta_mn||'—'}}</td><td>{{item.cuenta_me||'—'}}</td><td>{{item.detraccion?'Sí':'No'}}</td><td><span :class="item.activo?'ok':'bad'">{{item.activo?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">Estado</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>DOCUMENTO PARA COMPRAS</small><h2>{{editing?'Editar':'Nuevo'}} documento</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Nombre *<input v-model="form.nombre" maxlength="50" @input="form.nombre=form.nombre.toUpperCase()"></label><label>Tipo de operación *<select v-model="form.tipoope"><option value="0">Pago</option><option value="1">Ingreso</option><option value="2">Salida</option></select></label><label>Afectación *<select v-model="form.afectacion"><option value="S">Afecto</option><option value="N">Inafecto</option></select></label></div><div class="account-search"><input v-model="cuentaQuery" placeholder="Buscar cuenta por código o descripción" @keyup.enter.prevent="searchAccounts"><button type="button" :disabled="searching" @click="searchAccounts">Buscar cuentas</button></div><div class="grid"><label>Cuenta contable MN<select v-model="form.cuenta_contable_prov_mn"><option :value="null">Sin cuenta</option><option v-for="c in cuentas" :key="c.id" :value="c.id">{{c.cta_contable}} - {{c.descripcion}}</option></select></label><label>Cuenta contable ME<select v-model="form.cuenta_contable_prov_me"><option :value="null">Sin cuenta</option><option v-for="c in cuentas" :key="c.id" :value="c.id">{{c.cta_contable}} - {{c.descripcion}}</option></select></label></div><label class="check"><input v-model="form.detraccion" type="checkbox"> Aplica detracción</label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small,.dialog>header small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters,.account-search{margin-top:10px;padding:13px;display:flex;gap:7px;background:#fff}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.55rem;background:#fff}.filters input{margin-right:auto}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:980px;border-collapse:collapse;font-size:.52rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.ok,.bad{padding:4px 7px;border-radius:10px;font-size:.43rem}.ok{color:#287154;background:#e6f7ee}.bad{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button{padding:6px;border:0;border-radius:5px;font-size:.44rem}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center}.table-card>footer{padding:10px;display:flex;justify-content:center;gap:9px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 14px;font-size:.9rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.dialog label{display:grid;gap:5px;font-size:.5rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.account-search{padding:10px 0}.check{display:flex!important;align-items:center;margin-top:12px}.check input{width:auto}.dialog footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:720px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.grid{grid-template-columns:1fr}}
</style>
